glossary=[
dict(term='Tezaur / treasure',text='May mean the bank reserve, royal jewels, cultural heritage, securities or the entire evacuation. Always identify the asset category.'),
dict(term='Aur fin / чистое золото / fine gold',text='Pure-gold content, not necessarily the gross weight of alloyed coins or their containers. A monetary valuation is a third, distinct measure.'),
dict(term='Обезличено / obezlicheno',text='Depersonalized or no longer separately identified. In this case, accounting absorption and physical melting must not be assumed equivalent.'),
dict(term='Ссудная казна / Ssudnaia Kazna',text='Loan or deposit treasury; also rendered Sudnaia Kassa in secondary accounts. A cultural-storage location distinct from the BNR reserve’s initial Kremlin deposit.'),
dict(term='Наркомфин / Narkomfin / NKF',text='People’s Commissariat for Finance. Its dispatch and payment records are central to the proposed disposal trail.'),
dict(term='Госбанк / Gosbank',text='State Bank. The Issue or Emission Section is a distinct destination in the translated 1924 account of Austrian crowns.'),
dict(term='GARF / ГА РФ',text='State Archive of the Russian Federation. A cited shelfmark is not a verified current access permission.'),
dict(term='RGAE / РГАЭ',text='Russian State Archive of the Economy. Reported source of the May 1921 inventory and many Mosyakin facsimiles.'),
dict(term='RGASPI / РГАСПИ',text='Russian State Archive of Socio-Political History. Cited for Lenin/Sokolnikov correspondence and political decisions.'),
dict(term='Fond / opis / delo / list',text='Archive collection / inventory or series / file / folio. “Ob.” means verso. Record all levels and both sides when requesting copies.'),
dict(term='OS / NS',text='Old Style (Julian) / New Style (Gregorian). In 1916–1917, add 13 days when the original is actually Julian; do not convert an already normalized date again.'),
dict(term='Pietroasele / Pietroasa / Cloșca cu puii de aur',text='An identifiable ancient treasure returned in 1956, now associated with MNIR. Its return is not a return of the bank’s monetary reserve.'),
dict(term='Place-name aliases',text='Iași / Jassy; Chișinău / Kishinev; Bender / Tighina; Odesa / Odessa; Moscow / Moscova / Москва. Search historical spellings as well as modern ones.'),
dict(term='Person-name aliases',text='Schipor; Pokivaylova / Pokivailova / Покивайлова; Mosyakin / Mosiakin / Мосякин; Ganetsky / Ganețki / Ганецкий; Alsky / Alski / Альский.'),
]

